                            }
                        }
                        _ => preserve_default = PRESERVE_DEFAULT_VALUES,
                    }
                }
            }
            _ => path_value_hint = clap::ValueHint::AnyPath,
        }
    } else {
        target_value_hint = clap::ValueHint::DirPath;
    }
}

